  React.useEffect(() => {
    setState({ data: null, loading: true, error: null });
    setTimeout(() => {
      setState({
        data: { id: 1, name: 'Sample Data', source: url } as T,
        loading: false,
        error: null
      });
    }, 1000);
  }, [url]);

  return children(state);
}

ReactDOM.render(
  React.createElement(DataFetcher, { url: '/api/data' },
