function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  fallbackUI: (error: Error) => React.ReactNode
): React.ComponentType<P> {
  return class ErrorBoundary extends React.Component<P, { hasError: boolean; error: Error | null }> {
    constructor(props: P) {
      super(props);
      this.state = { hasError: false, error: null };
    }

    static getDerivedStateFromError(error: Error) {
      return { hasError: true, error };
    }

    render() {
      if (this.state.hasError) {
        return fallbackUI(this.state.error!);
      }
      return React.createElement(WrappedComponent, this.props);
    }
  };
}

function BuggyComponent() {
  throw new Error('Something broke!');
}

const SafeComponent = withErrorBoundary(BuggyComponent, (error) => {
  return React.createElement('div', { style: { color: 'red' } },
    'Error caught: ' + error.message
  );
});

ReactDOM.render(
  React.createElement(SafeComponent),
  document.getElementById('root')
);
